import {CHAPTERS,chapterKeys,CASES} from './curriculum.js';
import {PACKETS} from './packets.js';
import {subnet,tcpAck,delays,mss,fragment} from './calculators.js';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:4}).format(n);
const table=(headers,rows)=>`<div class="table-scroll"><table class="study-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const facts=items=>`<dl class="result-facts">${items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
const input=(name,label,value,type='text')=>`<label class="calculator-input">${label}<input name="${name}" type="${type}" value="${value}" ${type==='number'?'step="any"':''} required></label>`;

export class LearningHub{
 constructor(root,onSelect){this.root=root;this.onSelect=onSelect;this.layerId='application';this.tab='theory';this.packet='tcp';this.field='tcp-seq';this.open=new Map();this.render();}
 setLayer(id){if(id===this.layerId)return;this.layerId=id;const heading=this.root.querySelector('#study-context');if(heading)heading.textContent=chapterKeys(id).map(k=>CHAPTERS[k].name).join(' · ');if(this.tab==='theory')this.renderBody();}
 jump(tab){this.tab=tab;this.render();this.root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}
 render(){this.root.innerHTML=`<div class="study-heading"><div><span class="eyebrow">04 / 深入理解</span><h3>原理、字段与计算</h3><p>查看当前层的原理讲解，或切换到报文字段、计算工具和排查案例。</p></div><a href="./network-atlas-source.zip" class="download-source" download>下载源码 ↓</a></div><div class="study-context"><span class="status-dot"></span> 当前层：<b id="study-context">${chapterKeys(this.layerId).map(k=>CHAPTERS[k].name).join(' · ')}</b></div><nav class="study-tabs" aria-label="进阶学习栏目">${[['theory','原理讲解'],['fields','报文字段'],['tools','计算实验'],['cases','排查案例']].map(([key,title])=>`<button data-study-tab="${key}" class="${key===this.tab?'active':''}" aria-pressed="${key===this.tab}">${title}</button>`).join('')}</nav><div id="study-body"></div>`;this.root.querySelectorAll('[data-study-tab]').forEach(btn=>btn.addEventListener('click',()=>{this.tab=btn.dataset.studyTab;this.render();}));this.renderBody();}
 renderBody(){const body=this.root.querySelector('#study-body');if(this.tab==='theory')body.innerHTML=this.theory();if(this.tab==='fields'){body.innerHTML=this.fields();this.bindFields();}if(this.tab==='tools'){body.innerHTML=this.tools();this.bindTools();}if(this.tab==='cases')body.innerHTML=this.cases();body.querySelectorAll('details[data-study-open]').forEach(el=>el.addEventListener('toggle',()=>this.open.set(el.dataset.studyOpen,el.open)));}
 details(key,title,content,defaultOpen=false,extra=''){return `<details class="study-detail ${extra}" data-study-open="${key}" ${this.open.has(key)?this.open.get(key)?'open':'':defaultOpen?'open':''}><summary>${title}</summary><div class="study-detail-body">${content}</div></details>`;}
 theory(){return chapterKeys(this.layerId).map(key=>{const c=CHAPTERS[key];return `<div class="chapter-head"><h4>${c.name} · 学习目标</h4><ul class="goal-list">${c.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></div>${c.lessons.map((l,i)=>this.details(`lesson-${key}-${i}`,`<span class="lesson-index">${String(i+1).padStart(2,'0')}</span>${esc(l.title)}`,l.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')+(l.formula?`<div class="study-formula">${esc(l.formula)}</div>`:'')+(l.example?`<div class="worked-example"><b>例题 / 场景</b><p>${esc(l.example)}</p></div>`:''),i===0)).join('')}`;}).join('');}
 fields(){const p=PACKETS[this.packet];let grid;if(p.rows)grid=`<div class="packet-bit-scale"><span>0</span><span>15</span><span>31 bit</span></div><div class="packet-bit-grid">${p.rows.map(row=>`<div class="packet-bit-row">${row.map(f=>`<button style="flex:${f.bits}" data-field="${f.id}" class="${this.field===f.id?'active':''}" aria-pressed="${this.field===f.id}"><b>${esc(f.label)}</b><small>${esc(f.lengthLabel || f.bits+' bit')}</small></button>`).join('')}</div>`).join('')}</div>`;else grid=`<div class="packet-sequence">${p.sequence.map(f=>`<button data-field="${f.id}" class="${this.field===f.id?'active':''}" aria-pressed="${this.field===f.id}"><b>${esc(f.label)}</b><small>${f.bits?f.bits/8+'字节':'可变'}</small></button>`).join('')}</div>`;const all=p.rows?p.rows.flat():p.sequence;const f=all.find(f=>f.id===this.field)||all[0];return `<div class="packet-pickers">${Object.entries(PACKETS).map(([k,p])=>`<button data-packet="${k}" class="${k===this.packet?'active':''}">${p.name}</button>`).join('')}</div><p class="study-intro">点击字段，查看长度、语义和示例值。</p>${grid}<div class="field-explanation" aria-live="polite"><span class="eyebrow">SELECTED FIELD</span><h4>${esc(f.label)}</h4><p>${esc(f.description)}</p><code>${esc(f.example)}</code></div><p class="study-footnote">${esc(p.note)}</p><button class="study-link" id="field-layer">在3D模型中定位这一层 ↗</button>`;}
 bindFields(){this.root.querySelectorAll('[data-packet]').forEach(btn=>btn.addEventListener('click',()=>{this.packet=btn.dataset.packet;const p=PACKETS[this.packet];this.field=(p.rows?p.rows.flat():p.sequence)[0].id;this.renderBody();}));this.root.querySelectorAll('[data-field]').forEach(btn=>btn.addEventListener('click',()=>{this.field=btn.dataset.field;this.renderBody();}));this.root.querySelector('#field-layer').addEventListener('click',()=>this.onSelect(PACKETS[this.packet].layer));}
 tools(){return `<p class="study-intro">输入参数后查看结果和计算过程。各工具的适用条件列在结果下方。</p>
 ${this.details('tool-subnet','① CIDR与IPv4地址范围',`<form data-calc="subnet"><div class="calculator-grid">${input('ip','IPv4地址','192.168.10.130')}${input('prefix','前缀长度 /p','26','number')}</div><button class="calculate-button">计算地址范围</button><div class="calculator-result" aria-live="polite"></div></form>`,true)}
 ${this.details('tool-ack','② TCP序列号与确认号',`<form data-calc="ack"><div class="calculator-grid">${input('seq','序列号 seq','1001','number')}${input('payload','连续数据字节数','500','number')}</div><div class="checkbox-row"><label><input type="checkbox" name="syn">包含SYN</label><label><input type="checkbox" name="fin">包含FIN</label></div><button class="calculate-button">计算下一个期望确认号</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-delay','③ 发送时延、传播时延与BDP',`<form data-calc="delay"><div class="calculator-grid">${input('bytes','分组长度（字节）','1500','number')}${input('mbps','链路速率（Mb/s）','100','number')}${input('km','链路距离（km）','1000','number')}${input('velocity','传播速度（m/s）','200000000','number')}</div><button class="calculate-button">计算时延</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-mss','④ MTU与TCP载荷上限',`<form data-calc="mss"><div class="calculator-grid">${input('mtu','路径MTU（字节）','1500','number')}<label class="calculator-input">IP版本<select name="version"><option value="4">IPv4（基本头20字节）</option><option value="6">IPv6（基本头40字节）</option></select></label>${input('tcp','TCP首部（字节）','20','number')}</div><button class="calculate-button">计算TCP载荷上限</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 ${this.details('tool-fragments','⑤ IPv4分片与片偏移',`<form data-calc="fragments"><div class="calculator-grid">${input('payload','原始IP载荷（字节，不含头）','4000','number')}${input('mtu','下一跳MTU（字节）','1500','number')}${input('header','每片IPv4首部（字节）','20','number')}</div><button class="calculate-button">查看分片过程</button><div class="calculator-result" aria-live="polite"></div></form>`)}
 `;}
 bindTools(){this.root.querySelectorAll('[data-calc]').forEach(form=>{const calculate=()=>{const data=new FormData(form),get=k=>data.get(k),out=form.querySelector('.calculator-result');try{let result='';switch(form.dataset.calc){case'subnet':{const r=subnet(get('ip'),get('prefix'));result=facts([['子网掩码',r.mask],['网络 / 前缀起点',`${r.network}/${r.prefix}`],['广播',r.broadcast],['可用首地址',r.first],['可用末地址',r.last],['总地址 / 可用',`${format(r.total)} / ${format(r.usable)}`]])+`<code class="calculation-line">地址二进制：${r.binary}</code><p>${r.note}</p>`;break;}case'ack':{const r=tcpAck(get('seq'),get('payload'),data.has('syn'),data.has('fin'));result=facts([['下一个期望确认号（ack）',r.ack],['占用序号数量',r.used]])+`<code class="calculation-line">${r.formula}</code><p>${r.note}</p>`;break;}case'delay':{const r=delays(get('bytes'),get('mbps'),get('km'),get('velocity'));result=facts([['发送时延',`${format(r.transmission)} ms`],['单程传播时延',`${format(r.propagation)} ms`],['简化单程总时延',`${format(r.total)} ms`],['基于传播RTT的BDP',`${format(r.bdp)} 字节`]])+'<code class="calculation-line">发送：字节×8 ÷ 比特率；传播：距离 ÷ 速度</code>'+`<p>${r.note}</p>`;break;}case'mss':{const r=mss(get('mtu'),get('version'),get('tcp'));result=facts([['TCP载荷上限',`${r.mss} 字节`]])+`<code class="calculation-line">${get('mtu')} − ${r.ipHeader} − ${r.tcpHeader} = ${r.mss}</code><p>${r.note}</p>`;break;}case'fragments':{const r=fragment(get('payload'),get('mtu'),get('header'));result=table(['片','数据字节','IP总长','偏移 / 8字节','MF'],r.map(f=>[f.number,f.payload,f.total,f.offset,f.mf]))+'<p>允许IPv4分片；同一原始分组的分片保持相应标识。非末片载荷按8字节对齐，本例假设每片首部同长。</p>';break;}}out.innerHTML=result;out.classList.remove('error');}catch(e){out.textContent=e.message;out.classList.add('error');}};form.addEventListener('submit',e=>{e.preventDefault();calculate();});calculate();});}
 cases(){return `<p class="study-intro">每个案例包含故障现象、定位线索、排查命令和分析。使用命令前，将目标域名与接口名替换为实际值。</p>${CASES.map(c=>this.details('case-'+c.id,`<span class="case-layer">${CHAPTERS[c.layer].name}</span>${esc(c.title)}`,`<p><b>现象：</b>${esc(c.symptom)}</p><details class="case-reveal"><summary>① 展开定位线索</summary><ol>${c.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ol></details><details class="case-reveal"><summary>② 查看排查命令</summary>${c.commands.map(([os,cmd])=>`<b class="command-os">${esc(os)}</b><pre><code>${esc(cmd)}</code></pre>`).join('')}</details><details class="case-reveal"><summary>③ 查看分析与结论</summary><p>${esc(c.conclusion)}</p></details>`)).join('')}`;}
}
